      "一貫性（Consistency）とは、複数のトランザクションを同時に実行しても、ロックを一切かけずに常に処理速度を一定に保つ性質である。",
      "ハードディスクの物理故障（メディア障害）が発生した際、バックアップ時点の状態から更新前ログ（UNDOログ）を用いて障害直前の確定状態へ復元することをロールバックと呼ぶ。",
