      "× 計算誤りです。",
      "○ 正解！1 Byte ＝ 8 bit なので、600 MByte ＝ 600 × 8 ＝ 4,800 Mbit（メガビット）です。これを 80 Mbps（メガビット／秒）で割ると、4,800 ÷ 80 ＝「60 秒」となります。",
      "× 480秒ではありません。"
